import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

/// Vocabulary bundled with the app:
///
/// * `assets/vocabulary/words.json`: ~3,000 most useful words, generated by
///   `tool/vocab/build_vocab.py` from open datasets.
/// * `assets/vocabulary/packs.json`: hand-written career packs
///   (Pflege, IT & Büro).
///
/// No database: loaded once at startup and kept in memory.

enum Topic {
  basics('Grundlagen', 'Basics', Icons.waving_hand_outlined),
  everyday('Alltag', 'Everyday', Icons.chat_bubble_outline_rounded),
  people('Menschen', 'People', Icons.people_outline_rounded),
  time('Zeit', 'Time', Icons.schedule_rounded),
  food('Essen & Trinken', 'Food & drink', Icons.restaurant_outlined),
  home('Wohnen', 'Home', Icons.home_outlined),
  travel('Unterwegs', 'Getting around', Icons.directions_bus_outlined),
  work('Arbeit', 'Work & study', Icons.work_outline_rounded),
  health('Gesundheit', 'Health', Icons.favorite_border_rounded),
  nature('Natur', 'Nature', Icons.park_outlined),

  // Career packs: curated, job-specific vocabulary.
  care(
    'Pflege',
    'Nursing & care',
    Icons.medical_services_outlined,
    isPack: true,
  ),
  office('IT & Büro', 'IT & office', Icons.laptop_mac_rounded, isPack: true);

  const Topic(this.german, this.english, this.icon, {this.isPack = false});

  final String german;
  final String english;
  final IconData icon;

  /// Career packs are learned on purpose (from their topic page), not mixed
  /// into the general daily lesson.
  final bool isPack;

  static List<Topic> get general => values.where((t) => !t.isPack).toList();
  static List<Topic> get packs => values.where((t) => t.isPack).toList();

  List<GermanWord> get words => Vocabulary.instance.wordsIn(this);

  int get wordCount => Vocabulary.instance.countFor(this);

  static Topic parse(String name) =>
      Topic.values.firstWhere((t) => t.name == name, orElse: () => everyday);
}

/// CEFR level of a word, A1 (beginner) to B2 (upper intermediate).
/// Assigned by `tool/vocab/levels.py`; career-pack-only words have none.
enum CefrLevel {
  a1('A1'),
  a2('A2'),
  b1('B1'),
  b2('B2');

  const CefrLevel(this.code);

  final String code;

  /// The level after this one, or null at B2.
  CefrLevel? get next => index + 1 < values.length ? values[index + 1] : null;

  static CefrLevel? parse(String? name) {
    for (final l in values) {
      if (l.name == name) return l;
    }
    return null;
  }
}

class GermanWord {
  const GermanWord({
    required this.word,
    required this.article,
    required this.pos,
    required this.meaning,
    required this.topic,
    this.plural = '',
    this.rank = 0,
    this.example = '',
    this.exampleMeaning = '',
    this.level,
  });

  factory GermanWord.fromJson(Map<String, dynamic> j) => GermanWord(
    word: j['word'] as String,
    article: j['article'] as String? ?? '',
    pos: j['pos'] as String? ?? '',
    meaning: j['meaning'] as String? ?? '',
    plural: j['plural'] as String? ?? '',
    topic: Topic.parse(j['topic'] as String? ?? ''),
    rank: j['rank'] as int? ?? 0,
    example: j['example'] as String? ?? '',
    exampleMeaning: j['exampleMeaning'] as String? ?? '',
    level: CefrLevel.parse(j['level'] as String?),
  );

  final String word;

  /// der / die / das, or empty for non-nouns.
  final String article;

  /// Wiktionary part of speech: noun, verb, adj, adv, prep, …
  final String pos;
  final String meaning;
  final String plural;
  final Topic topic;

  /// Frequency rank (1 = most common). 0 for hand-picked essentials.
  final int rank;
  final String example;
  final String exampleMeaning;

  /// Null for career-pack-only words (packs are learned at any level).
  final CefrLevel? level;

  bool get hasExample => example.isNotEmpty;

  bool matches(String query) {
    final q = query.trim().toLowerCase();
    if (q.isEmpty) return true;
    return '$article $word'.toLowerCase().contains(q) ||
        meaning.toLowerCase().contains(q);
  }
}

class Vocabulary {
  Vocabulary(
    this.words, {
    this.sources = const {},
    Map<Topic, List<GermanWord>> packs = const {},
  }) : _byTopic = {
         for (final t in Topic.values)
           t: t.isPack
               ? List.unmodifiable(packs[t] ?? const <GermanWord>[])
               : List.unmodifiable(words.where((w) => w.topic == t)),
       };

  static const packsPath = 'assets/vocabulary/packs.json';

  static const assetPath = 'assets/vocabulary/words.json';

  final List<GermanWord> words;

  /// Dataset credits, shown in Profile.
  final Map<String, String> sources;
  final Map<Topic, List<GermanWord>> _byTopic;

  /// Words in a topic. A pack can include words that also belong to a
  /// general topic (e.g. "der Fehler" is in Everyday and in IT & Büro).
  List<GermanWord> wordsIn(Topic topic) => _byTopic[topic] ?? const [];

  int countFor(Topic topic) => wordsIn(topic).length;

  static Vocabulary? _instance;

  static Vocabulary get instance {
    final v = _instance;
    if (v == null) {
      throw StateError('Call Vocabulary.load() before using vocabulary.');
    }
    return v;
  }

  static Vocabulary parse(String source, {String? packsSource}) {
    final json = jsonDecode(source) as Map<String, dynamic>;
    final words = (json['words'] as List)
        .map((e) => GermanWord.fromJson(e as Map<String, dynamic>))
        .toList();
    final sources = (json['sources'] as Map?)?.cast<String, String>() ?? {};

    // Career packs: reuse an existing word when it is already in the main
    // list (same spelling + word class), otherwise add it as pack-only.
    final packs = <Topic, List<GermanWord>>{};
    if (packsSource != null) {
      final byKey = {for (final w in words) '${w.word}|${w.pos}': w};
      final pj = jsonDecode(packsSource) as Map<String, dynamic>;
      (pj['packs'] as Map<String, dynamic>).forEach((name, rows) {
        final topic = Topic.parse(name);
        final list = <GermanWord>[];
        for (final r in (rows as List).cast<List<dynamic>>()) {
          final word = GermanWord(
            article: r[0] as String,
            word: r[1] as String,
            pos: r[2] as String,
            meaning: r[3] as String,
            plural: r[4] as String,
            example: r[5] as String,
            exampleMeaning: r[6] as String,
            topic: topic,
          );
          final existing = byKey['${word.word}|${word.pos}'];
          if (existing != null) {
            // Same word (same progress key), but shown with the job meaning
            // and example: "die Station" = ward, not bus stop.
            list.add(
              GermanWord(
                article: word.article,
                word: word.word,
                pos: word.pos,
                meaning: word.meaning,
                plural: word.plural.isNotEmpty ? word.plural : existing.plural,
                example: word.example,
                exampleMeaning: word.exampleMeaning,
                topic: existing.topic,
                rank: existing.rank,
                level: existing.level,
              ),
            );
          } else {
            words.add(word);
            byKey['${word.word}|${word.pos}'] = word;
            list.add(word);
          }
        }
        packs[topic] = list;
      });
    }
    return Vocabulary(List.unmodifiable(words), sources: sources, packs: packs);
  }

  /// Loads the bundled word lists once; later calls are no-ops.
  static Future<Vocabulary> load({AssetBundle? bundle}) async {
    final existing = _instance;
    if (existing != null) return existing;
    final b = bundle ?? rootBundle;
    final source = await b.loadString(assetPath);
    final packs = await b.loadString(packsPath);
    return _instance = parse(source, packsSource: packs);
  }
}

/// All words, most useful first.
List<GermanWord> get vocabulary => Vocabulary.instance.words;
